  function routingView() { const q = state.routeQuery.toLowerCase(), list = routes().filter(v => JSON.stringify(v).toLowerCase().includes(q)); return `<div class="workspace-toolbar"><div><span class="eyebrow">Traffic policy</span><p>Stable public identities with visible execution order and backend compilation.</p></div><button class="button primary" data-action="add-route">+ Create route</button></div><div class="route-banner"><div class="route-banner-icon">⇄</div><div><b>One public model. Many reliable targets.</b><span>NexaRoute owns the decision; clients never need provider-specific credentials.</span></div><span class="route-banner-count">${num(routes().length)} routes</span></div><div class="list-toolbar"><label class="search-box"><span>⌕</span><input id="route-filter" type="search" value="${esc(state.routeQuery)}" placeholder="Search routes or public models…"></label><span class="subtle">Advanced primitives stay available below the simple path. Candidate pools remain backend-owned.</span></div>${list.length ? `<div class="route-grid">${list.map(routeCard).join('')}</div>` : `<div class="empty-state"><div class="empty-icon">⇄</div><h3>${routes().length ? 'No matching routes' : 'Create your first public route'}</h3><p>Choose a stable model name, select eligible deployments and let the backend compile the route.</p><button class="button primary" data-action="add-route">Create route</button></div>`}<section class="advanced-panel"><details><summary><span>Advanced routing objects</span><small>Candidate pools · profiles · fallback chains · virtual endpoints</small></summary><div class="advanced-grid"><pre>${esc(JSON.stringify({ candidate_pools: state.snap.candidate_pools || [], route_profiles: state.snap.route_profiles || [] }, null, 2))}</pre><pre>${esc(JSON.stringify({ virtual_endpoints: state.snap.virtual_endpoints || [], fallback_chains: state.snap.fallback_chains || [] }, null, 2))}</pre></div></details></section>`; }
