  async function startSSE() { if (!canReadAudit()) { if (state.sseAbort) state.sseAbort.abort(); state.sseAbort = null; if (state.sseReconnect) { clearTimeout(state.sseReconnect); state.sseReconnect = null; } return; } if (state.sseAbort) state.sseAbort.abort(); if (state.sseReconnect) { clearTimeout(state.sseReconnect); state.sseReconnect = null; } const ac = state.sseAbort = new AbortController(); const cursor = state.eventEpoch ? `&since=${encodeURIComponent(state.eventSeq)}` : ''; try { const r = await fetch(`/admin/api/events/stream?limit=50${cursor}`, { headers: state.adminKey ? { 'x-admin-key': state.adminKey } : {}, credentials: 'same-origin', cache: 'no-store', signal: ac.signal }); if (!r.ok) throw Error(`SSE ${r.status}`); setConnection(true); const reader = r.body?.getReader(); if (!reader) return; const dec = new TextDecoder(); let buf = ''; while (!ac.signal.aborted) { const x = await reader.read(); if (x.done) break; buf += dec.decode(x.value, { stream: true }); let cut; while ((cut = buf.indexOf('\n\n')) >= 0) { const frame = buf.slice(0, cut); buf = buf.slice(cut + 2); const line = frame.split('\n').find(v => v.startsWith('data: ')); if (!line) continue; try { const ev = JSON.parse(line.slice(6)); const epoch = Number(ev.epoch || 0), seq = Number(ev.seq || 0); if (epoch && state.eventEpoch && epoch !== state.eventEpoch) { await resyncSnapshot(); continue; } if (epoch && !state.eventEpoch) state.eventEpoch = epoch; if (seq && state.eventSeq && seq > state.eventSeq + 1) { await resyncSnapshot(); continue; } if (seq && seq <= state.eventSeq) continue; state.eventSeq = Math.max(state.eventSeq, seq); state.snap.events = [...(state.snap.events || []), ev].slice(-100); window.NexaRouteVisualAgent?.handleEvent(ev); if (state.page === 'overview' || state.page === 'activity') render(); } catch {} } } if (!ac.signal.aborted) { setConnection(false, true); state.sseReconnect = setTimeout(() => startSSE(), 1000); } } catch (e) { if (!ac.signal.aborted) { setConnection(false, true); state.sseReconnect = setTimeout(() => startSSE(), 1000); } } }

  async function downloadUsage() { const headers = { Accept: 'text/csv' }; if (state.adminKey) headers['x-admin-key'] = state.adminKey; const response = await fetch('/admin/api/usage/identities?format=csv', { headers, credentials: 'same-origin', cache: 'no-store' }); if (!response.ok) { if (response.status === 401) { if (state.auth?.oidc_enabled) window.location.assign('/admin/auth/login'); else if (!state.adminKey && state.auth?.emergency_access_enabled && state.auth?.api_key_configured) openAuth(); } throw Error(`CSV download failed (HTTP ${response.status})`); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'nexaroute-identity-usage.csv'; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); notice('Identity usage CSV downloaded.'); }
    const actions = { 'save-profile-privacy': async e => { const id = e.target.dataset.id; const profile = (state.snap.route_profiles || []).find(p => p.id === id); if (!profile) { notice('Profile not found in the current snapshot.', true); return; } const privacy = $(`#privacy-${CSS.escape(id)}`)?.value || 'any'; await api(`/admin/api/route-profiles/${encodeURIComponent(id)}`, { method: 'PUT', ...body({ ...profile, privacy }) }); notice(`Privacy for ${id} set to ${privacy === 'no_training' ? 'no training only' : 'any provider'}.`); await refresh(); }, 'reload-evals': () => { state.evalsLoaded = false; ensureEvals(); render(); }, 'run-eval': async () => { const dep = $('#eval-deployment')?.value, suite = $('#eval-suite')?.value.trim(); if (!dep || !suite) { notice('Pick a deployment and enter a suite id.', true); return; } const res = await api('/admin/api/evaluation/run', { method: 'POST', ...body({ suite_id: suite, deployment_id: dep }) }); const box = $('#eval-run-result'); if (box) box.innerHTML = `<p class="good-text">Run accepted: ${esc(res.id || res.run_id || 'see recent runs below')}.</p>`; notice('Evaluation run accepted.'); state.evalsLoaded = false; ensureEvals(); }, 'reload-audit': () => { state.auditLoaded = false; ensureAudit(); render(); }, 'export-audit-json': () => exportAuditJSON(), 'export-audit-csv': () => exportAuditCSV(), 'export-cost-csv': () => exportCostCSV(), 'export-cost-json': () => exportCostJSON(), 'add-provider': () => openProvider(), 'create-video': openVideoCreate, 'refresh-video': () => { state.videoDisabled = false; state.videoError = ''; refreshVideo(); }, 'save-video-token': () => { state.videoToken = $('#video-token').value.trim(); if (state.videoToken) sessionStorage.setItem('nexaroute_video_token', state.videoToken); else sessionStorage.removeItem('nexaroute_video_token'); notice(state.videoToken ? 'Video token saved for this browser session.' : 'Video token cleared.'); state.videoDisabled = false; state.videoError = ''; refreshVideo(); }, 'cancel-video': async e => { const btn = e.target.closest('[data-action="cancel-video"]'); await videoApi('/v1/video/jobs/' + encodeURIComponent(btn.dataset.id) + '/cancel', { method: 'POST' }); notice('Video job cancellation requested.'); await refreshVideo(); }, 'download-video': async e => { const btn = e.target.closest('[data-action="download-video"]'); await downloadVideoAsset(btn.dataset.id, btn.dataset.assetId, btn.dataset.filename); }, 'example-shot-plan': () => { const field = $('#v-shot-plan'); if (field) field.value = JSON.stringify([{ shot_id: 'arrival', duration_seconds: 4, prompt: 'Wide establishing shot of Persepolis at sunrise, historically grounded ancient Persian architecture', camera_movement: 'slow cinematic pan' }, { shot_id: 'walkthrough', duration_seconds: 4, prompt: 'A time-travelling guide walks toward the monumental staircase at Persepolis', subject_action: 'walks forward while looking at the reliefs' }], null, 2); }, 'edit-provider': e => openProvider(e.target.dataset.id), 'provider-test': e => testProvider(e.target.dataset.id), 'add-route': () => openRoute(), 'edit-route': e => openRoute(e.target.dataset.id), 'connect-route': e => connectRoute(e.target.dataset.id),  'refresh': refresh, 'close-modal': closeModal, 'save-modal': () => state.modal?.save?.(), 'toggle-drain': async () => { const res = await api('/admin/api/drain', { method: 'POST', ...body({ draining: !state.drain.draining }) }); state.drain = res; notice(res.draining ? 'Graceful drain enabled.' : 'Traffic resumed.'); render(); }, 'rollback': async () => { const res = await api('/admin/api/config/history', { method: 'POST', ...body({ steps: 1, expected_revision: state.history.revision }) }); notice(`Rolled back to revision ${res.revision}.`); await refresh(); }, 'create-key': () => openModal('Create virtual key', `<div class="form-grid"><div class="field"><label for="key-name">Name</label><input id="key-name" required></div><div class="field"><label for="key-tenant">Tenant ID</label><input id="key-tenant"></div><div class="field"><label for="key-role">Role</label><select id="key-role"><option>developer</option><option>operator</option><option>admin</option></select></div><div class="field"><label for="key-rpm">RPM</label><input id="key-rpm" type="number" min="0" value="0"></div><div class="field"><label for="key-tpm">TPM</label><input id="key-tpm" type="number" min="0" value="0"></div><div class="field"><label for="key-project">Project ID</label><input id="key-project"></div><div class="field"><label for="key-team">Team ID</label><input id="key-team"></div><div class="field"><label for="key-models">Allowed models (comma-separated, blank = all)</label><input id="key-models"></div><div class="field"><label for="key-routes">Allowed routes (comma-separated, blank = all)</label><input id="key-routes"></div></div>`, async () => { const res = await api('/admin/api/client-keys', { method: 'POST', ...body({ name: $('#key-name').value.trim(), tenant_id: $('#key-tenant').value.trim(), project_id: $('#key-project').value.trim(), team_id: $('#key-team').value.trim(), role: $('#key-role').value, rpm: Number($('#key-rpm').value || 0), tpm: Number($('#key-tpm').value || 0), allowed_models: $('#key-models').value.split(',').map(x => x.trim()).filter(Boolean), allowed_routes: $('#key-routes').value.split(',').map(x => x.trim()).filter(Boolean) }) }); closeModal(); openModal('Virtual key created', `<p>Copy this key now. It will not be shown again.</p><div class="field"><input readonly value="${esc(res.key || '')}"></div>`, null, 'Close'); await refresh(); }), 'rotate-key': async e => { const res = await api(`/admin/api/client-keys/${encodeURIComponent(e.target.dataset.id)}/rotate`, { method: 'POST', ...body({}) }); openModal('Virtual key rotated', `<p>Copy this replacement key now. It will not be shown again.</p><div class="field"><input readonly value="${esc(res.key || '')}"></div>`, null, 'Close'); await refresh(); }, 'revoke-key': async e => { await api(`/admin/api/client-keys/${encodeURIComponent(e.target.dataset.id)}`, { method: 'DELETE' }); notice('Virtual key revoked.'); await refresh(); }, 'download-usage': downloadUsage, 'detect-models': detectModels, 'select-all-models': () => $$('#model-list input').forEach(x => x.checked = true), 'add-manual-model': () => { const i = $('#p-manual'), v = i.value.trim(); if (!v) return; $('#model-list').insertAdjacentHTML('beforeend', modelRow(v)); i.value = ''; }, 'test-model': async e => { const m = e.target.dataset.model; notice(`Testing ${m} against the provider…`); try { const res = await api('/admin/api/provider-test', { method: 'POST', ...body({ ...readProvider(), test_models: [m] }) }); notice(res.results?.[0]?.ok ? `${m} passed.` : `${m} failed.`, !res.results?.[0]?.ok); } catch (x) { notice(x.message, true); } }, 'copy': e => navigator.clipboard?.writeText(e.target.dataset.copy).then(() => notice('Copied to clipboard.')), 'test-api': async e => { const btn = e.target.closest('[data-action="test-api"]'); const url = btn.dataset.url; btn.disabled = true; btn.textContent = 'Testing...'; try { const r = await fetch(url, { headers: { Accept: 'application/json' } }); if (!r.ok) throw new Error('HTTP ' + r.status); const j = await r.json(); const n = (j.data || []).length; notice('API reachable: ' + n + ' model(s) listed.'); } catch (x) { notice('API test failed: ' + x.message, true); } btn.disabled = false; btn.textContent = 'Test API'; }, 'save-settings': async () => { const r = { ...(state.snap.config?.routing || {}), strategy: $('#setting-strategy').value, session_affinity: $('#setting-affinity').value === 'true', max_attempts: Number(r.max_attempts || 1) }, p = { ...(state.snap.config?.probe || {}), enabled: $('#setting-probe').value === 'true' }; await api('/admin/api/settings', { method: 'PUT', ...body({ client_base_url: $('#setting-client-base-url').value.trim(), routing: r, probe: p }) }); notice('Settings saved.'); await refresh(); } };  function openConfirm(title, text, save) { openModal(title, `<p class="muted">${esc(text)}</p>`, save, 'Delete'); }
  actions['delete-route'] = e => openConfirm('Delete saved route?', 'This changes backend configuration and removes the selected route.', async () => { await api(`/admin/api/simple-routes/${encodeURIComponent(e.target.dataset.id)}`, { method: 'DELETE' }); closeModal(); notice('Route deleted.'); await refresh(); });
  document.addEventListener('click', e => { const page = e.target.closest('[data-page]'); if (page) { state.page = page.dataset.page; render(); return; } const go = e.target.closest('[data-go]'); if (go) { state.page = go.dataset.go; render(); return; } const tab = e.target.closest('[data-activity-tab]'); if (tab) { state.activityTab = tab.dataset.activityTab; render(); return; } const act = e.target.closest('[data-action]'); if (!act) return; const fn = actions[act.dataset.action]; if (fn) Promise.resolve(fn(e)).catch(x => { if (isVideoDisabledError(x)) { if (state.page === 'video') { state.videoDisabled = true; state.videoError = ''; state.videoProviders = []; state.videoJobs = []; stopVideoPolling(); renderVideoOnly(); } return; } notice(x.message, true); }); });
  $('#theme-toggle').addEventListener('click', () => { state.theme = state.theme === 'dark' ? 'light' : 'dark'; localStorage.setItem('nexaroute_theme', state.theme); document.documentElement.dataset.theme = state.theme; $('#theme-toggle').textContent = state.theme === 'dark' ? 'Light mode' : 'Dark mode'; });
  $('#auth-control')?.addEventListener('click', async () => { if (state.auth?.authenticated && state.auth?.oidc_enabled) { try { await api('/admin/auth/logout', { method: 'POST' }); state.csrfToken = ''; window.location.reload(); } catch (e) { notice(e.message, true); } } else if (state.auth?.authenticated) { state.adminKey = ''; state.csrfToken = ''; window.location.reload(); } else if (state.auth?.oidc_enabled) { window.location.assign('/admin/auth/login'); } else openAuth(); });
  document.documentElement.dataset.theme = state.theme; $('#theme-toggle').textContent = state.theme === 'dark' ? 'Light mode' : 'Dark mode'; render(); initializeAuth().then(ok => { if (ok) refresh(); }); window.addEventListener('pagehide', () => { state.sseAbort?.abort(); if (state.sseReconnect) clearTimeout(state.sseReconnect); });
